  if (!Object.values(Role).includes(proposedRoleStr as Role)) {
    throw new AuthorizationSecurityException(
      `Attempted to assign illegal or unrecognized role: ${proposedRoleStr}`,
      'SEC_ERR_UNKNOWN_ROLE'
    );
  }
