  if (actor.tenantId !== context.tenantId) {
    throw new AuthorizationSecurityException(
      `Tenant Context Mismatch: Principal (${actor.tenantId}) mutated outside scope (${context.tenantId}).`,
      'SEC_ERR_CROSS_TENANT_BREACH'
    );
  }

