  const REQUIRED_PERMISSION = 'user:edit_role';
  if (!actor.permissions || !actor.permissions.has(REQUIRED_PERMISSION)) {
    throw new AuthorizationSecurityException(
      `Principal lacks fundamental capability: ${REQUIRED_PERMISSION}`,
      'SEC_ERR_MISSING_CAPABILITY'
    );
  }

