  const targetCurrentWeight = ROLE_HIERARCHY_WEIGHT[target.role];
  if (targetCurrentWeight === undefined) {
    throw new AuthorizationSecurityException(
      'Target user possesses a corrupted or unranked internal state.',
      'SEC_ERR_CORRUPT_TARGET_STATE'
    );
  }

