+import type { OrderDiscount } from "../types.js";
+
+export interface DiscountStrategy {
+  calculateDiscount(subtotalCents: number, discount?: OrderDiscount): number;
+}
+
+export class PercentageDiscountStrategy implements DiscountStrategy {
+  calculateDiscount(subtotalCents: number, discount?: OrderDiscount): number {
+    if (!discount || discount.type !== "percentage") {
+      return 0;
+    }
+    const pct = Math.max(0, Math.min(100, discount.value));
+    return Math.round((subtotalCents * pct) / 100);
+  }
+}
+
+export class FixedCentsDiscountStrategy implements DiscountStrategy {
+  calculateDiscount(subtotalCents: number, discount?: OrderDiscount): number {
+    if (!discount || discount.type !== "fixed_cents") {
+      return 0;
+    }
+    return Math.min(subtotalCents, Math.max(0, discount.value));
+  }
+}
+
+export class StandardDiscountStrategy implements DiscountStrategy {
+  private percentageStrategy = new PercentageDiscountStrategy();
+  private fixedCentsStrategy = new FixedCentsDiscountStrategy();
+
+  calculateDiscount(subtotalCents: number, discount?: OrderDiscount): number {
+    if (!discount) {
+      return 0;
+    }
+
+    if (discount.type === "percentage") {
+      return this.percentageStrategy.calculateDiscount(subtotalCents, discount);
+    } else if (discount.type === "fixed_cents") {
+      return this.fixedCentsStrategy.calculateDiscount(subtotalCents, discount);
+    }
+
+    return 0;
+  }
+}
+
+export class DiscountCalculator {
+  constructor(
+    private strategy: DiscountStrategy = new StandardDiscountStrategy()
+  ) {}
+
+  calculate(subtotalCents: number, discount?: OrderDiscount): number {
+    return this.strategy.calculateDiscount(subtotalCents, discount);
+  }
+}
