+import type { OrderItem } from "../types.js";
+
+/**
+ * Tax rates by item category.
+ *
+ * Food:        0 %
+ * Clothing:    5 %
+ * Electronics: 15 %
+ * General:     10 %  (default)
+ */
+const TAX_RATES: Record<OrderItem["category"], number> = {
+  food: 0,
+  clothing: 0.05,
+  electronics: 0.15,
+  general: 0.1,
+};
+
+/**
+ * Computes the total tax in cents.
+ *
+ * Each item's effective taxable amount is its line subtotal scaled by
+ * `discountRatio` (= discountedSubtotal / subtotal), so that proportional
+ * discounts reduce the taxable base evenly across all items.
+ *
+ * @param items           The order line items.
+ * @param subtotalCents   The pre-discount subtotal.
+ * @param discountedSubtotalCents  The subtotal after discounts are applied.
+ */
+export function calculateTax(
+  items: OrderItem[],
+  subtotalCents: number,
+  discountedSubtotalCents: number
+): number {
+  const discountRatio =
+    subtotalCents > 0 ? discountedSubtotalCents / subtotalCents : 1;
+
+  let taxCents = 0;
+
+  for (const item of items) {
+    const itemSubtotal = item.unitPriceCents * item.quantity * discountRatio;
+    const rate = TAX_RATES[item.category] ?? TAX_RATES.general;
+    taxCents += Math.round(itemSubtotal * rate);
+  }
+
+  return taxCents;
+}

