+import type { OrderItem } from "../types.js";
+
+const CATEGORY_TAX_RATES: Readonly<Record<OrderItem["category"], number>> = {
+  food: 0,
+  clothing: 0.05,
+  electronics: 0.15,
+  general: 0.1
+};
+
+/** Calculates category tax after distributing the order discount proportionally. */
+export class CategoryTaxCalculator {
+  calculate(
+    items: OrderItem[],
+    subtotalCents: number,
+    discountedSubtotalCents: number
+  ): number {
+    const discountRatio =
+      subtotalCents > 0 ? discountedSubtotalCents / subtotalCents : 1;
+    let taxCents = 0;
+
+    for (const item of items) {
+      const itemSubtotalCents =
+        item.unitPriceCents * item.quantity * discountRatio;
+      const taxRate = CATEGORY_TAX_RATES[item.category] ?? 0.1;
+      taxCents += Math.round(itemSubtotalCents * taxRate);
+    }
+
+    return taxCents;
+  }
+}
