+import type { OrderDiscount } from "../types.js";
+
+/** Applies the supported discount strategies to an order subtotal. */
+export class DiscountCalculator {
+  calculate(subtotalCents: number, discount?: OrderDiscount): number {
+    if (!discount) {
+      return 0;
+    }
+
+    if (discount.type === "percentage") {
+      const percentage = Math.max(0, Math.min(100, discount.value));
+      return Math.round((subtotalCents * percentage) / 100);
+    }
+
+    if (discount.type === "fixed_cents") {
+      return Math.min(subtotalCents, Math.max(0, discount.value));
+    }
+
+    return 0;
+  }
+}
